# Python-style number formatting for microgpt.mlpl's output lines.
# to_string prints the shortest round-trip decimal; microgpt.py uses
# f"{x:4d}", f"{x:2d}" and f"{x:.4f}".

def u:pad_left(s, width) {
  "Right-align string s in width columns (like Python's {:>width}).";
  out = s;
  while lt(str_len(out), width) { out = str_concat(" ", out) };
  out
}

def u:fmt_int(x, width) {
  "f'{x:widthd}' for a non-negative integer x.";
  u:pad_left(to_string(round(x)), width)
}

def u:fmt_fixed4(x) {
  "f'{x:.4f}' for x >= 0 (round half up at the 4th decimal).";
  scaled = floor(x * 10000 + 0.5);
  whole = floor(scaled / 10000);
  frac = to_string(scaled - whole * 10000);
  while lt(str_len(frac), 4) { frac = str_concat("0", frac) };
  str_concat(str_concat(to_string(whole), "."), frac)
}

def u:write(s) {
  "Write s to stdout with no trailing newline (for Python's end='\\r').";
  unwrap(write_stdout(tokenize_bytes(s)))
}
EOF
cat > tests/test_format.mlpl <<'EOF'
# Python-style formatting helpers (lib/format.mlpl).
include "lib/format.mlpl";

@test {name: "integers are right-aligned like {:4d}", tags: ["format"]}
def u:test_fmt_int() {
  "Python: f'{7:4d}' == '   7', f'{1000:4d}' == '1000', f'{12345:4d}' == '12345'.";
  u:assert_text_eq(u:fmt_int(7, 4), "   7", "pad")?;
  u:assert_text_eq(u:fmt_int(1000, 4), "1000", "exact width")?;
  u:assert_text_eq(u:fmt_int(12345, 4), "12345", "overflow is not truncated")?;
  u:assert_text_eq(u:fmt_int(3, 2), " 3", "sample index")
}

