        ("wpe", [BLOCK_SIZE, N_EMBD]),
        ("lm_head", [v, N_EMBD]),
        ("layer0_attn_wq", [N_EMBD, N_EMBD]),
        ("layer0_attn_wk", [N_EMBD, N_EMBD]),
        ("layer0_attn_wv", [N_EMBD, N_EMBD]),
        ("layer0_attn_wo", [N_EMBD, N_EMBD]),
        ("layer0_mlp_fc1", [4 * N_EMBD, N_EMBD]),
        ("layer0_mlp_fc2", [N_EMBD, 4 * N_EMBD]),
    ];
    let weights = shapes
        .iter()
        .map(|&(name, shape)| {
            let values = (0..shape[0] * shape[1]).map(|_| rng.gauss(0.0, INIT_STD)).collect();
            (name, shape, values)
        })
        .collect();
    let uniforms = (0..NUM_UNIFORMS).map(|_| rng.uniform()).collect();
    Dump { num_docs: docs.len(), order, weights, uniforms }
}

/// Shortest round-trip decimal for every f64 (Rust's `{:?}`), as a JSON array.
fn json_f64s(xs: &[f64]) -> String {
    let parts: Vec<String> = xs.iter().map(|x| format!("{x:?}")).collect();
    format!("[{}]", parts.join(", "))
}

fn to_json(d: &Dump) -> String {
    let mut out = String::from("{\n");
    writeln!(out, "  \"num_docs\": {},", d.num_docs).unwrap();
    let order: Vec<String> = d.order.iter().map(usize::to_string).collect();
    writeln!(out, "  \"order\": [{}],", order.join(", ")).unwrap();
    for (name, shape, values) in &d.weights {
        writeln!(out, "  \"{name}\": {},", json_f64s(values)).unwrap();
        writeln!(out, "  \"{name}_shape\": [{}, {}],", shape[0], shape[1]).unwrap();
    }
    writeln!(out, "  \"uniforms\": {}", json_f64s(&d.uniforms)).unwrap();
    out.push('}');
    out
}

fn main() {
    let path = std::env::args().nth(1).unwrap_or_else(|| "input.txt".into());
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        eprintln!("rs-init-dump: cannot read {path}: {e}");
        std::process::exit(1);
    });
    println!("{}", to_json(&dump(&text)));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn splitmix64_matches_reference_values() {
        // splitmix64 seeded with 0: the published first outputs.
        let mut rng = Rng::new(0);
        assert_eq!(rng.next_u64(), 0xE220_A839_7B1D_CDAF);
        assert_eq!(rng.next_u64(), 0x6E78_9E6A_A1B9_65F4);
    }

    #[test]
    fn dump_has_microgpt_shapes_and_draw_counts() {
        let text = "emma\n\n olivia \nava\n";
        let d = dump(text);
        assert_eq!(d.num_docs, 3, "blank line dropped, whitespace trimmed");
        let mut sorted = d.order.clone();
        sorted.sort_unstable();
        assert_eq!(sorted, vec![0, 1, 2], "order is a permutation");
        // vocab: a e i l m o v = 7 chars + BOS
        let total: usize = d.weights.iter().map(|(_, s, v)| {
            assert_eq!(v.len(), s[0] * s[1]);
            v.len()
        }).sum();
        assert_eq!(total, 8 * 16 * 2 + 16 * 16 * 5 + 64 * 16 * 2);
        assert_eq!(d.uniforms.len(), NUM_UNIFORMS);
        assert!(d.uniforms.iter().all(|u| (0.0..1.0).contains(u)));
    }

    #[test]
    fn weights_are_gaussian_with_init_std() {
        let d = dump("abcdefghijklmnopqrstuvwxyz\n");
        let all: Vec<f64> = d.weights.iter().flat_map(|(_, _, v)| v.iter().copied()).collect();
        assert_eq!(all.len(), 4192, "same count as microgpt.py");
        let n = all.len() as f64;
        let mean = all.iter().sum::<f64>() / n;
        let std = (all.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / n).sqrt();
        assert!(mean.abs() < 0.005, "mean {mean}");
        assert!((std - INIT_STD).abs() < 0.004, "std {std}");
    }

    #[test]
    fn json_numbers_round_trip() {
        let xs = [0.1, -2.5e-17, 0.30000000000000004, 1.0];
        let s = json_f64s(&xs);
        let back: Vec<f64> =
            s.trim_matches(['[', ']']).split(", ").map(|p| p.parse().unwrap()).collect();
        assert_eq!(back, xs);
    }
}
