# Let there be a Dataset `docs`: one name per line of input.txt.
# Python shuffles the list in place; here the docs stay in file order and
# `order` is the shuffled visiting order (a permutation of doc indices).
d = unwrap(u:dataset(load("input.txt")));
order = shuffle(range(d.n_docs), 42);
print("num docs:", to_string(d.n_docs));
num_steps = 1000;
train_docs = u:doc_batch(d, u:gather1(order, mod(range(num_steps), d.n_docs)), block_size);
train_tokens = train_docs.tokens;
train_n = train_docs.n;
# Keep what inference needs, then drop the big arrays: in this
# interpreter every u: call copies the global environment, so a 228k
# corpus left in scope costs ~0.05 ms per call (docs/benchmarks.md).
uchars = d.uchars;
BOS = d.bos;
expunge(["d", "order", "train_docs", "txt"]);
# Inference: may the model babble back to us. temperature in (0, 1]
# controls the "creativity" of generated text, low to high. One seeded
# uniform stream drives every draw (row = sample, column = position).
include "lib/sample.mlpl";
temperature = 0.5;
num_samples = 20;
sample_uniforms = random(4242, [num_samples, block_size]);
print("");
print("--- inference (new, hallucinated names) ---");
# (A while loop: repeat/train/for bodies reject string-valued statements
# in mlpl-repl 0.22.0 -- docs/upstream-issues.md (j).)
sample_idx = 0;
while lt(sample_idx, num_samples) {
  name = u:ids_to_text(u:generate(take(sample_uniforms, 0, sample_idx), temperature));
  print(str_concat(str_concat(str_concat("sample ", u:fmt_int(sample_idx + 1, 2)), ": "), name));
  sample_idx = sample_idx + 1
}

exit(0)

