cat > zz_c.mlpl <<'EOF'
b = tokenize_bytes(load("input.txt"));
stream = concat([26], (b - 97) * ne(b, 10) + 26 * eq(b, 10));
X = shift_pairs_x(stream, 16);
Y = shift_pairs_y(stream, 16);
V = 27; d = 16;
model = chain(embed(V, d, 1), residual(chain(rms_norm(d), causal_attention(d, 4, 2))), residual(chain(rms_norm(d), linear(d, 4 * d, 3), relu_layer(), linear(4 * d, d, 4))), rms_norm(d), linear(d, V, 5));
print("params", param_count(model));
B = 4;
picks = reshape(mod(floor(random(42, [1000 * B]) * len(X)), len(X)), [1000, B]);
t0 = clock_ms();
train 1000 {
  rows = take(picks, 0, step);
  xb = gather_rows(X, rows);
  yb = gather_rows(Y, rows);
  adam(cross_entropy(apply(model, xb), yb), model, 0.01 * (1 - step / 1000), 0.85, 0.99, 0.00000001)
};
print("train ms", clock_ms() - t0);
m = reshape(last_losses, [10, 100]);
print("window means", reduce_add(m, 1) / 100);
prompt = [26];
t0 = clock_ms();
i = 0;
while lt(i, 10) {
  gs = gen_state(model, prompt);
  out = [26];
  k = 0; done = 0;
  while lt(k, 16) * (1 - done) {
    tok = sample(gen_logits(gs), 0.5, 1000 * i + k);
    if eq(tok, 26) { done = 1 } else { out = concat(out, [tok]); gen_append(gs, tok) };
    k = k + 1
  };
  print(decode_bytes(u_dummy = 0 * 0 + at([0], 0) + 97 + reshape(gather_rows(reshape(out, [len(out), 1]), range(len(out) - 1) + 1), [len(out) - 1])));
  i = i + 1
};
print("gen ms", clock_ms() - t0);
exit(0)
EOF
