ann = {
'def u:causal_mask(n) {': '''@formula "M[t,s] = 0 if s ≤ t;  M[t,s] = −10⁹ if s > t   (t, s = 0..n−1)"
@ascii "M[t,s] = 0 if s <= t; M[t,s] = -1e9 if s > t   (t, s = 0..n-1)"
''',
'def u:linear(x, w) {': '''@formula "linear(X, W) = X Wᵀ,   X ∈ ℝ^(n×n_in), W ∈ ℝ^(n_out×n_in)"
@ascii "linear(X, W) = X W^T,   X is n x n_in, W is n_out x n_in"
''',
'def u:rmsnorm(x) {': '''@formula "rmsnorm(x)[t,j] = x[t,j] / √( (1/d) ∑(k=1..d) x[t,k]² + ε ),   d = 16, ε = 10⁻⁵"
@ascii "rmsnorm(x)[t,j] = x[t,j] / sqrt((1/d) * SUM(k=1..d) x[t,k]^2 + eps),   d = 16, eps = 1e-5"
''',
'def u:head(q, k, v, sel, mask) {': '''@formula "head_h(Q,K,V) = softmax( (Q S_h)(K S_h)ᵀ / √d_h + M ) (V S_h) S_hᵀ,   d_h = 4"
@ascii "head_h(Q,K,V) = softmax((Q S_h)(K S_h)^T / sqrt(d_h) + M) (V S_h) S_h^T,   d_h = 4"
''',
'def u:loss(inp, tgt, mask) {': '''@formula "L = −(1/n) ∑(t=0..n−1) log softmax(z_t)[y_t],   z = gpt(inp)"
@ascii "L = -(1/n) * SUM(t=0..n-1) log softmax(z_t)[y_t],   z = gpt(inp)"
''',
'def u:sample_token(logits, temperature, u) {': '''@formula "i* = min{ i : ∑(j=0..i) p_j ≥ u · ∑(j=0..V−1) p_j },   p = softmax(z / τ)"
@ascii "i* = min{ i : SUM(j=0..i) p_j >= u * SUM(j=0..V-1) p_j },   p = softmax(z / tau)"
''',
}
for p in ['lib/model.mlpl','lib/sample.mlpl','docs/literate/microgpt-faithful.org']:
    s=open(p).read()
    for k,v in ann.items():
        if k in s:
            assert s.count(k)==1,(p,k)
            s=s.replace(k, v+k)
    open(p,'w').write(s)
EOF
