#+TITLE: microgpt in idiomatic MLPL
#+SUBTITLE: The same capability as =microgpt.py=, written with sw-MLPL's Model DSL
#+AUTHOR: Mike Wright
#+DATE: 2026-09-23
#+OPTIONS: toc:2 num:t ^:{}
#+PROPERTY: header-args:mlpl :session idiomatic :results output :exports both :tangle microgpt-idiomatic.mlpl
#+HTML_HEAD: <style>
#+HTML_HEAD: pre.src, pre.example { background: #fafafa; border: 1px solid #e0e0e0; border-radius: 4px; }
#+HTML_HEAD: .org-mlpl-builtin, .org-builtin { color: #6f42c1; }
